DROP POLICY "Admins add branch assignments" ON public.staff_branch_assignments;
CREATE POLICY "Admins add branch assignments" ON public.staff_branch_assignments FOR INSERT TO authenticated WITH CHECK (public.is_staff_admin(auth.uid()) AND user_id <> auth.uid() AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=user_id AND p.is_active) AND (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role='super_admin') OR (branch_name=(SELECT branch FROM public.profiles WHERE id=auth.uid()) AND EXISTS (SELECT 1 FROM public.staff_invitations i WHERE i.claimed_by=user_id AND i.branch=branch_name AND i.status='claimed') AND NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=staff_branch_assignments.user_id AND r.role='super_admin'))));
DROP POLICY "Admins remove branch assignments" ON public.staff_branch_assignments;
CREATE POLICY "Admins remove branch assignments" ON public.staff_branch_assignments FOR DELETE TO authenticated USING (public.is_staff_admin(auth.uid()) AND user_id <> auth.uid() AND (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role='super_admin') OR (branch_name=(SELECT branch FROM public.profiles WHERE id=auth.uid()) AND EXISTS (SELECT 1 FROM public.staff_invitations i WHERE i.claimed_by=user_id AND i.branch=branch_name AND i.status='claimed') AND NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=staff_branch_assignments.user_id AND r.role='super_admin'))));